/**
 * Byte and encoding primitives.
 *
 * The internal byte type across every module in this port is `Uint8Array`,
 * standing in for Python's immutable `bytes`. Everything here is pure JS: no
 * platform hashing, no Buffer, no TextEncoder.
 */

/** Lookup table for lowercase hex formatting ('00' .. 'ff'). */
const HEX_DIGITS = (() => {
  const table = new Array(256);
  const chars = '0123456789abcdef';
  for (let i = 0; i < 256; i += 1) {
    table[i] = chars[(i >> 4) & 0xf] + chars[i & 0xf];
  }
  return table;
})();

/** True for the byte-ish inputs we accept (Uint8Array and friends). */
export function isBytes(value) {
  return value instanceof Uint8Array;
}

/**
 * Encode a JS string to UTF-8 bytes, mirroring Python's `str.encode("UTF-8")`.
 *
 * JS strings are UTF-16 code-unit sequences, so surrogate pairs are combined
 * into a single 4-byte sequence. An unpaired surrogate cannot be represented in
 * UTF-8; we emit U+FFFD for it (WHATWG behaviour) since such a code unit can
 * never reach us from argv anyway -- see the notes in test7.mjs.
 */
export function utf8Encode(text) {
  const str = String(text);
  // Worst case is 3 bytes per code unit (4 bytes come from 2 units).
  const out = new Uint8Array(str.length * 3);
  let n = 0;
  for (let i = 0; i < str.length; i += 1) {
    let cp = str.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff) {
      // High surrogate: pair it with a following low surrogate if present.
      const next = i + 1 < str.length ? str.charCodeAt(i + 1) : 0;
      if (next >= 0xdc00 && next <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
        i += 1;
      } else {
        cp = 0xfffd; // lone high surrogate
      }
    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
      cp = 0xfffd; // lone low surrogate
    }

    if (cp < 0x80) {
      out[n++] = cp;
    } else if (cp < 0x800) {
      out[n++] = 0xc0 | (cp >> 6);
      out[n++] = 0x80 | (cp & 0x3f);
    } else if (cp < 0x10000) {
      out[n++] = 0xe0 | (cp >> 12);
      out[n++] = 0x80 | ((cp >> 6) & 0x3f);
      out[n++] = 0x80 | (cp & 0x3f);
    } else {
      out[n++] = 0xf0 | (cp >> 18);
      out[n++] = 0x80 | ((cp >> 12) & 0x3f);
      out[n++] = 0x80 | ((cp >> 6) & 0x3f);
      out[n++] = 0x80 | (cp & 0x3f);
    }
  }
  return out.subarray(0, n);
}

/**
 * Coerce str-or-bytes to bytes, the way the Python pbkdf2 package coerces its
 * passphrase/salt arguments (`if not isinstance(x, bytes): x = x.encode("UTF-8")`).
 */
export function asBytes(value) {
  if (isBytes(value)) return value;
  if (typeof value === 'string') return utf8Encode(value);
  if (Array.isArray(value)) return new Uint8Array(value);
  throw new TypeError('expected a string or Uint8Array');
}

/** Lowercase hex with no separators, i.e. Python's `bytes.hex()`. */
export function toHex(bytes) {
  const b = asBytes(bytes);
  let out = '';
  for (let i = 0; i < b.length; i += 1) out += HEX_DIGITS[b[i]];
  return out;
}

/** Concatenate any number of byte arrays into one fresh array. */
export function concat(...parts) {
  let total = 0;
  for (const part of parts) total += part.length;
  const out = new Uint8Array(total);
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

/** Copying slice (never a view), so callers can't alias internal buffers. */
export function slice(bytes, start, end) {
  return bytes.slice(start, end);
}

/**
 * Store an unsigned big-endian integer of `width` bytes at `offset`.
 * Used for PBKDF2's block counter and SHA-1's length field.
 */
export function writeUintBE(target, offset, value, width) {
  let v = value;
  for (let i = width - 1; i >= 0; i -= 1) {
    target[offset + i] = v & 0xff;
    v = Math.floor(v / 256);
  }
  return target;
}

/** Python `struct.pack("!L", value)`: 4-byte big-endian unsigned. */
export function packUint32BE(value) {
  if (!Number.isInteger(value) || value < 0 || value > 0xffffffff) {
    throw new RangeError('value out of range for 32-bit big-endian packing');
  }
  return writeUintBE(new Uint8Array(4), 0, value, 4);
}

/** Python `struct.pack("!Q", value)`: 8-byte big-endian unsigned. */
export function packUint64BE(value) {
  return writeUintBE(new Uint8Array(8), 0, value, 8);
}

/** Elementwise XOR of two equal-length arrays (Python pbkdf2's `strxor`). */
export function xor(a, b) {
  if (a.length !== b.length) {
    throw new RangeError('xor operands must be the same length');
  }
  const out = new Uint8Array(a.length);
  for (let i = 0; i < a.length; i += 1) out[i] = a[i] ^ b[i];
  return out;
}

/** In-place XOR of `target` with `source` (same length). Returns `target`. */
export function xorInto(target, source) {
  if (target.length !== source.length) {
    throw new RangeError('xor operands must be the same length');
  }
  for (let i = 0; i < target.length; i += 1) target[i] ^= source[i];
  return target;
}

/** XOR every byte with one constant -- HMAC's ipad/opad construction. */
export function xorWithByte(bytes, constant) {
  const out = new Uint8Array(bytes.length);
  for (let i = 0; i < bytes.length; i += 1) out[i] = bytes[i] ^ constant;
  return out;
}

/** Zero-extend (or truncate) to exactly `length` bytes. */
export function zeroPad(bytes, length) {
  const out = new Uint8Array(length);
  out.set(bytes.subarray(0, length));
  return out;
}

/**
 * SHA-1 (FIPS 180-4) implemented from scratch in pure JS.
 *
 * The module exports a "digest module" object shaped like Python's hashlib
 * modules (`digestSize`, `blockSize`, `new()`), which is the seam that lets
 * hmac.mjs stay algorithm-agnostic.
 */

import { asBytes, toHex, writeUintBE } from './bytes.mjs';

const DIGEST_SIZE = 20;
const BLOCK_SIZE = 64;

/** Round constants, one per 20-round group. */
const K0 = 0x5a827999;
const K1 = 0x6ed9eba1;
const K2 = 0x8f1bbcdc;
const K3 = 0xca62c1d6;

/** Rotate a 32-bit word left by `n` bits. */
function rotl(word, n) {
  return (word << n) | (word >>> (32 - n));
}

/**
 * Streaming SHA-1 state. `update()` may be called any number of times with
 * chunks of any size; `digest()` is non-destructive (like hashlib) and may be
 * called repeatedly, and updates may continue afterwards.
 */
export class SHA1Hash {
  constructor() {
    /** Chaining variables, held as signed int32 for fast wrap-around math. */
    this.state = new Int32Array([0x67452301, 0xefcdab89 | 0, 0x98badcfe | 0, 0x10325476, 0xc3d2e1f0 | 0]);
    /** Partial (< 64 byte) tail of the message. */
    this.block = new Uint8Array(BLOCK_SIZE);
    this.blockLength = 0;
    /** Total number of bytes fed in so far. */
    this.byteCount = 0;
    /** Scratch message schedule, reused across blocks. */
    this.w = new Int32Array(80);
  }

  get digestSize() {
    return DIGEST_SIZE;
  }

  get blockSize() {
    return BLOCK_SIZE;
  }

  /** Deep copy of the hash state, so digest() can finalise without side effects. */
  copy() {
    const clone = new SHA1Hash();
    clone.state.set(this.state);
    clone.block.set(this.block);
    clone.blockLength = this.blockLength;
    clone.byteCount = this.byteCount;
    return clone;
  }

  /** Absorb more data. Accepts bytes or a string (UTF-8 encoded). */
  update(data) {
    const input = asBytes(data);
    this.byteCount += input.length;

    let offset = 0;

    // Top up a partially filled block first.
    if (this.blockLength > 0) {
      const need = BLOCK_SIZE - this.blockLength;
      const take = Math.min(need, input.length);
      this.block.set(input.subarray(0, take), this.blockLength);
      this.blockLength += take;
      offset = take;
      if (this.blockLength < BLOCK_SIZE) return this;
      this._compress(this.block, 0);
      this.blockLength = 0;
    }

    // Consume whole blocks straight out of the input.
    while (offset + BLOCK_SIZE <= input.length) {
      this._compress(input, offset);
      offset += BLOCK_SIZE;
    }

    // Buffer whatever is left over.
    if (offset < input.length) {
      const rest = input.subarray(offset);
      this.block.set(rest, 0);
      this.blockLength = rest.length;
    }
    return this;
  }

  /** The 20-byte digest of everything absorbed so far. */
  digest() {
    // Work on a clone so this instance stays usable, matching hashlib.
    const h = this.copy();

    // Padding: 0x80, then zeros so that (length % 64) == 56, then the 64-bit
    // big-endian bit count. blockLength is in [0, 63], so the two arms below
    // cover every boundary case (55/56/63/64/119/120 ...).
    const padZeroRun = h.blockLength < 56 ? 56 - h.blockLength : 120 - h.blockLength;
    const tail = new Uint8Array(padZeroRun + 8);
    tail[0] = 0x80;

    // bitCount = byteCount * 8, split exactly into two 32-bit halves so that
    // huge inputs never lose precision.
    const high = Math.floor(h.byteCount / 0x20000000);
    const low = (h.byteCount % 0x20000000) * 8;
    writeUintBE(tail, padZeroRun, high, 4);
    writeUintBE(tail, padZeroRun + 4, low, 4);
    h.update(tail);

    const out = new Uint8Array(DIGEST_SIZE);
    for (let i = 0; i < 5; i += 1) {
      writeUintBE(out, i * 4, h.state[i] >>> 0, 4);
    }
    return out;
  }

  /** Lowercase hex digest, i.e. hashlib's `hexdigest()`. */
  hexdigest() {
    return toHex(this.digest());
  }

  /** Core compression function over one 64-byte block of `bytes` at `offset`. */
  _compress(bytes, offset) {
    const w = this.w;

    // Load the block as 16 big-endian words, then expand to 80.
    for (let i = 0; i < 16; i += 1) {
      const p = offset + i * 4;
      w[i] = (bytes[p] << 24) | (bytes[p + 1] << 16) | (bytes[p + 2] << 8) | bytes[p + 3];
    }
    for (let i = 16; i < 80; i += 1) {
      w[i] = rotl(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    }

    let a = this.state[0];
    let b = this.state[1];
    let c = this.state[2];
    let d = this.state[3];
    let e = this.state[4];

    for (let i = 0; i < 80; i += 1) {
      let f;
      let k;
      if (i < 20) {
        f = (b & c) | (~b & d);
        k = K0;
      } else if (i < 40) {
        f = b ^ c ^ d;
        k = K1;
      } else if (i < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = K2;
      } else {
        f = b ^ c ^ d;
        k = K3;
      }
      // Sum in floating point (exact below 2^53) then truncate to int32.
      const temp = (rotl(a, 5) + f + e + k + w[i]) | 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }

    this.state[0] = (this.state[0] + a) | 0;
    this.state[1] = (this.state[1] + b) | 0;
    this.state[2] = (this.state[2] + c) | 0;
    this.state[3] = (this.state[3] + d) | 0;
    this.state[4] = (this.state[4] + e) | 0;
  }
}

/**
 * Digest-module interface: the shape hmac.mjs and pbkdf2.mjs are parameterised
 * over, mirroring Python's `digestmodule` argument.
 */
export const SHA1 = {
  name: 'sha1',
  digestSize: DIGEST_SIZE,
  blockSize: BLOCK_SIZE,

  /** Fresh hash object, optionally seeded with data (hashlib's `sha1.new()`). */
  new(data) {
    const h = new SHA1Hash();
    if (data !== undefined && data !== null) h.update(data);
    return h;
  },

  /** Alias of `new()` for callers that dislike the reserved word. */
  create(data) {
    return SHA1.new(data);
  },

  /** One-shot helper: digest of a single input. */
  digest(data) {
    return SHA1.new(data).digest();
  },

  /** One-shot helper returning lowercase hex. */
  hexdigest(data) {
    return toHex(SHA1.digest(data));
  },
};

export default SHA1;

/**
 * Generic HMAC (RFC 2104), parameterised over an injected digest module.
 *
 * This mirrors the Python seam that pbkdf2 uses: `macmodule.new(key, msg,
 * digestmodule).digest()`. Any object exposing `{ digestSize, blockSize, new() }`
 * works here, so the algorithm is never hard-wired to SHA-1.
 */

import { asBytes, toHex, xorWithByte, zeroPad } from './bytes.mjs';
import { SHA1 } from './sha1.mjs';

const IPAD_BYTE = 0x36;
const OPAD_BYTE = 0x5c;

/** Marker used to build copies without redoing the key schedule. */
const CLONE = Symbol('hmac.clone');

export class HMAC {
  /**
   * @param {Uint8Array|string} key      MAC key (strings are UTF-8 encoded).
   * @param {Uint8Array|string} [msg]    Optional initial message chunk.
   * @param {object} [digestmodule]      Digest module, defaults to SHA-1.
   */
  constructor(key, msg, digestmodule = SHA1) {
    if (key === CLONE) return; // populated by copy() below

    if (!digestmodule || typeof digestmodule.new !== 'function') {
      throw new TypeError('digestmodule must expose new(), digestSize and blockSize');
    }

    this.digestmodule = digestmodule;
    this.digestSize = digestmodule.digestSize;
    this.blockSize = digestmodule.blockSize;

    // RFC 2104: keys longer than the block size are hashed down first, then
    // every key is zero-padded out to exactly one block.
    let k = asBytes(key);
    if (k.length > this.blockSize) {
      k = digestmodule.new(k).digest();
    }
    k = zeroPad(k, this.blockSize);

    this.inner = digestmodule.new(xorWithByte(k, IPAD_BYTE));
    this.outer = digestmodule.new(xorWithByte(k, OPAD_BYTE));

    if (msg !== undefined && msg !== null) this.update(msg);
  }

  /** Absorb more message data. */
  update(msg) {
    this.inner.update(msg);
    return this;
  }

  /**
   * Snapshot of the keyed state. Copying a "key only" HMAC and updating the
   * copy avoids recomputing the key schedule for every PRF call.
   */
  copy() {
    const clone = new HMAC(CLONE);
    clone.digestmodule = this.digestmodule;
    clone.digestSize = this.digestSize;
    clone.blockSize = this.blockSize;
    clone.inner = this.inner.copy();
    clone.outer = this.outer.copy();
    return clone;
  }

  /** H(K^opad || H(K^ipad || message)). Non-destructive, like Python's hmac. */
  digest() {
    const outer = this.outer.copy();
    outer.update(this.inner.digest());
    return outer.digest();
  }

  /** Lowercase hex form of digest(). */
  hexdigest() {
    return toHex(this.digest());
  }
}

/**
 * MAC-module interface, shaped like Python's `hmac` module so it can be passed
 * as pbkdf2's `macmodule` argument.
 */
export const HMACModule = {
  name: 'hmac',
  HMAC,
  new(key, msg, digestmodule = SHA1) {
    return new HMAC(key, msg, digestmodule);
  },
  digest(key, msg, digestmodule = SHA1) {
    return new HMAC(key, msg, digestmodule).digest();
  },
};

/** Convenience one-shot: HMAC digest of `msg` under `key`. */
export function hmacDigest(key, msg, digestmodule = SHA1) {
  return new HMAC(key, msg, digestmodule).digest();
}

export default HMACModule;

/**
 * PBKDF2 (RFC 2898 / PKCS#5 v2.0) as a readable keystream, mirroring the API
 * surface of Dwayne Litzenberger's `pbkdf2` PyPI package.
 *
 * The distinguishing feature of that package (versus hashlib.pbkdf2_hmac) is
 * that `read(n)` is a *stream*: derived blocks T_1, T_2, ... are produced on
 * demand, n bytes are handed back, and any surplus stays buffered for the next
 * read. With SHA-1 (20-byte blocks) a `read(24)` therefore consumes T_1 in full
 * plus the first 4 bytes of T_2, leaving 16 bytes buffered.
 */

import { asBytes, concat, packUint32BE, toHex, xorInto } from './bytes.mjs';
import { SHA1 } from './sha1.mjs';
import { HMACModule } from './hmac.mjs';

/** Largest block index representable in the 4-byte INT32_BE counter. */
const MAX_BLOCKS = 0xffffffff;

export class PBKDF2 {
  /**
   * @param {Uint8Array|string} passphrase  UTF-8 encoded if a string.
   * @param {Uint8Array|string} salt        UTF-8 encoded if a string.
   * @param {number} [iterations=1000]      Iteration count c.
   * @param {object} [digestmodule=SHA1]    Digest module for the PRF.
   * @param {object} [macmodule=HMACModule] MAC module wrapping the digest.
   */
  constructor(passphrase, salt, iterations = 1000, digestmodule = SHA1, macmodule = HMACModule) {
    if (!Number.isInteger(iterations) || iterations < 1) {
      throw new RangeError('iterations must be an integer >= 1');
    }

    this.passphrase = asBytes(passphrase);
    this.salt = asBytes(salt);
    this.iterations = iterations;
    this.digestmodule = digestmodule;
    this.macmodule = macmodule;

    /** Size of one derived block, hLen in RFC 2898 (20 for SHA-1). */
    this.blockLength = digestmodule.digestSize;

    /** Leftover keystream bytes from the previous read(). */
    this.buffer = new Uint8Array(0);
    /** Index of the highest block already generated; blocks are 1-based. */
    this.blockNum = 0;
    this.closed = false;

    // The PRF key (the passphrase) never changes, so precompute the HMAC key
    // schedule once and clone it per call instead of re-padding every time.
    this.prfTemplate = macmodule.new(this.passphrase, undefined, digestmodule);
  }

  /** PRF(passphrase, msg) -- HMAC-SHA1 by default. */
  pseudorandom(msg) {
    return this.prfTemplate.copy().update(msg).digest();
  }

  /**
   * Read `count` bytes of keystream, generating whole blocks as needed and
   * buffering the remainder. Equivalent to the Python package's `read()`.
   */
  read(count) {
    if (this.closed) throw new Error('file-like object is closed');
    if (!Number.isInteger(count) || count < 0) {
      throw new RangeError('count must be a non-negative integer');
    }

    const parts = [this.buffer];
    let size = this.buffer.length;
    let i = this.blockNum;
    while (size < count) {
      i += 1;
      const block = this._deriveBlock(i);
      parts.push(block);
      size += block.length;
    }

    const buf = concat(...parts);
    this.blockNum = i;
    this.buffer = buf.slice(count);
    return buf.slice(0, count);
  }

  /** Read `count` bytes and return them as a lowercase hex string. */
  hexread(count) {
    return toHex(this.read(count));
  }

  /** Release the derived state; further reads raise, like the Python class. */
  close() {
    if (!this.closed) {
      this.passphrase = new Uint8Array(0);
      this.salt = new Uint8Array(0);
      this.buffer = new Uint8Array(0);
      this.prfTemplate = null;
      this.closed = true;
    }
  }

  /**
   * T_i = U_1 ^ U_2 ^ ... ^ U_c, where
   *   U_1 = PRF(P, S || INT32_BE(i)) and U_j = PRF(P, U_{j-1}).
   */
  _deriveBlock(i) {
    if (i < 1 || i > MAX_BLOCKS) {
      throw new RangeError('PBKDF2 block index out of range');
    }
    let u = this.pseudorandom(concat(this.salt, packUint32BE(i)));
    const result = u.slice(); // accumulator, XOR-folded in place
    for (let j = 2; j <= this.iterations; j += 1) {
      u = this.pseudorandom(u);
      xorInto(result, u);
    }
    return result;
  }
}

/**
 * Module-level convenience mirroring `pbkdf2.crypt`-style one-shot use: derive
 * exactly `dkLen` bytes and discard the stream.
 */
export function pbkdf2(passphrase, salt, dkLen, iterations = 1000, digestmodule = SHA1) {
  const stream = new PBKDF2(passphrase, salt, iterations, digestmodule);
  const out = stream.read(dkLen);
  stream.close();
  return out;
}

export default PBKDF2;

/**
 * A minimal, behaviour-compatible port of the slice of Python's `argparse` that
 * this script exercises: long options with a single value, `-h/--help`, prefix
 * abbreviation, `--` handling, and byte-identical usage/help/error output.
 *
 * The parsing loop deliberately follows CPython's `_parse_known_args`
 * structure (classify every argv token as option / plain-arg / separator, then
 * consume options left to right) because the observable error *precedence*
 * falls out of that structure:
 *
 *   1. `-h`/`--help` anywhere it is read as an option  -> help, exit 0
 *   2. `argument --x: expected one argument`           -> exit 2
 *   3. `the following arguments are required: ...`     -> exit 2
 *   4. `unrecognized arguments: ...`                   -> exit 2
 */

/** Matches what Python's `_negative_number_matcher` matches (\d == Unicode Nd). */
const NEGATIVE_NUMBER_RE = /^-[\p{Nd}]+$|^-[\p{Nd}]*\.[\p{Nd}]+$/u;

/** argparse HelpFormatter defaults. */
const INDENT = 2;
const MAX_HELP_POSITION = 24;

/**
 * Thrown to unwind out of the parser instead of calling process.exit() deep in
 * the call stack. The entry point turns this into stream writes plus an exit
 * code, which also guarantees output is flushed before the process ends.
 */
export class ParserExit extends Error {
  constructor(code, text, stream) {
    super(`parser exit ${code}`);
    this.name = 'ParserExit';
    this.code = code;
    this.text = text;
    this.stream = stream; // 'stdout' | 'stderr'
  }
}

/** Python's %r for a plain string: single quotes, minimal escaping. */
function repr(value) {
  return `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

export class ArgumentParser {
  constructor({ prog = 'prog', addHelp = true, prefixChars = '-', allowAbbrev = true } = {}) {
    this.prog = prog;
    this.prefixChars = prefixChars;
    this.allowAbbrev = allowAbbrev;

    /** All actions in declaration order -- drives usage, help and the required list. */
    this.actions = [];
    /** option string -> action, in insertion order (ambiguity lists use this order). */
    this.optionStringActions = new Map();
    /** Set when a registered option string itself looks like a negative number. */
    this.hasNegativeNumberOptionals = false;

    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        nargs: 0,
        isHelp: true,
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * Register an option. `nargs` is 1 (takes a value) or 0 (a flag).
   * Only optional (dash-prefixed) arguments are supported, which is all the
   * ported script declares.
   */
  addArgument(optionStrings, { nargs = 1, required = false, help = null, metavar = null, isHelp = false } = {}) {
    const strings = Array.isArray(optionStrings) ? optionStrings.slice() : [optionStrings];
    if (strings.length === 0 || !strings.every((s) => this.prefixChars.includes(s[0]))) {
      throw new Error('only optional (prefixed) arguments are supported');
    }
    // dest comes from the first long option, stripped of its prefix chars.
    const long = strings.find((s) => s.length > 1 && this.prefixChars.includes(s[1])) || strings[0];
    const dest = long.replace(new RegExp(`^[${this.prefixChars}]+`), '').replace(/-/g, '_');

    const action = {
      optionStrings: strings,
      dest,
      nargs,
      required,
      help,
      metavar: metavar || dest.toUpperCase(),
      isHelp,
    };
    this.actions.push(action);
    for (const s of strings) {
      this.optionStringActions.set(s, action);
      if (NEGATIVE_NUMBER_RE.test(s)) this.hasNegativeNumberOptionals = true;
    }
    return action;
  }

  // ---------------------------------------------------------------- formatting

  /** How an action appears in the usage line: `--a A`, or `-h`. */
  _formatUsagePart(action) {
    const head = action.optionStrings[0];
    const body = action.nargs === 0 ? head : `${head} ${action.metavar}`;
    return action.required ? body : `[${body}]`;
  }

  /** How an action appears in the options list: `-h, --help`, `--a A`. */
  _formatInvocation(action) {
    if (action.nargs === 0) return action.optionStrings.join(', ');
    return action.optionStrings.map((s) => `${s} ${action.metavar}`).join(', ');
  }

  formatUsage() {
    const parts = this.actions.map((a) => this._formatUsagePart(a));
    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
  }

  formatHelp() {
    // Column math straight out of argparse's HelpFormatter.
    const maxLength = Math.max(...this.actions.map((a) => this._formatInvocation(a).length + INDENT));
    const helpPosition = Math.min(maxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - INDENT - 2;

    let out = `${this.formatUsage()}\noptions:\n`;
    for (const action of this.actions) {
      const invocation = this._formatInvocation(action);
      if (!action.help) {
        out += `${' '.repeat(INDENT)}${invocation}\n`;
      } else if (invocation.length <= actionWidth) {
        out += `${' '.repeat(INDENT)}${invocation.padEnd(actionWidth)}  ${action.help}\n`;
      } else {
        // Too wide for the column: help text starts on the following line.
        out += `${' '.repeat(INDENT)}${invocation}\n${' '.repeat(helpPosition)}${action.help}\n`;
      }
    }
    return out;
  }

  // -------------------------------------------------------------------- exits

  /** `usage` + `prog: error: message` on stderr, exit status 2. */
  error(message) {
    throw new ParserExit(2, `${this.formatUsage()}${this.prog}: error: ${message}\n`, 'stderr');
  }

  /** `argument -h/--help: message` style errors. */
  _argumentError(action, message) {
    const name = action ? action.optionStrings.join('/') : null;
    this.error(name ? `argument ${name}: ${message}` : message);
  }

  /** Help text on stdout, exit status 0. */
  printHelp() {
    throw new ParserExit(0, this.formatHelp(), 'stdout');
  }

  // ------------------------------------------------------------------ parsing

  /**
   * Classify one token. Returns null if it should be treated as a plain
   * argument, otherwise a tuple describing the option it names (with a null
   * action when the option is unknown).
   */
  _parseOptional(argString) {
    if (!argString) return null; // '' is a value, never an option
    if (!this.prefixChars.includes(argString[0])) return null;

    if (this.optionStringActions.has(argString)) {
      return { action: this.optionStringActions.get(argString), optionString: argString, sep: null, explicitArg: null };
    }
    if (argString.length === 1) return null; // a bare '-'

    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      if (this.optionStringActions.has(optionString)) {
        return {
          action: this.optionStringActions.get(optionString),
          optionString,
          sep: '=',
          explicitArg: argString.slice(eq + 1),
        };
      }
    }

    const tuples = this._getOptionTuples(argString);
    if (tuples.length > 1) {
      const options = tuples.map((t) => t.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (tuples.length === 1) return tuples[0];

    // Bare negative numbers are values, not options, unless an option string
    // itself looks like one.
    if (NEGATIVE_NUMBER_RE.test(argString) && !this.hasNegativeNumberOptionals) return null;
    // Something with a space in it was surely meant as a value.
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, sep: null, explicitArg: null };
  }

  /** Abbreviation / concatenation matching, mirroring `_get_option_tuples`. */
  _getOptionTuples(argString) {
    const result = [];
    const chars = this.prefixChars;

    if (chars.includes(argString[0]) && chars.includes(argString[1])) {
      // Long option: `--pre` or `--pre=value`.
      if (!this.allowAbbrev) return result;
      const eq = argString.indexOf('=');
      const optionPrefix = eq === -1 ? argString : argString.slice(0, eq);
      const explicitArg = eq === -1 ? null : argString.slice(eq + 1);
      const sep = eq === -1 ? null : '=';
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, sep, explicitArg });
        }
      }
    } else if (chars.includes(argString[0]) && !chars.includes(argString[1])) {
      // Single-dash option, possibly with its value glued on: `-xVALUE`.
      const optionPrefix = argString;
      const shortOptionPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString === shortOptionPrefix) {
          // sep is '' (falsy) so the cluster-splitting path stays reachable.
          result.push({ action, optionString, sep: '', explicitArg: shortExplicitArg });
        } else if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, sep: null, explicitArg: null });
        }
      }
    }
    return result;
  }

  /**
   * How many following tokens an action consumes, given the pattern of what
   * follows. For options, argparse strips the dash-tolerance from the pattern,
   * which is why `--a -- x` fails rather than skipping the separator.
   */
  _matchArgument(action, pattern) {
    if (action.nargs === 0) return 0;
    if (pattern.startsWith('A')) return 1;
    this._argumentError(action, 'expected one argument');
    return 0; // unreachable
  }

  /** Parse argv, exiting via ParserExit on help or any error. */
  parseArgs(argv) {
    const args = Array.from(argv);

    // --- Pass 1: classify every token ------------------------------------
    // 'O' = option, 'A' = plain argument, '-' = the `--` separator itself.
    // Everything after `--` is forced to 'A'.
    const pattern = [];
    const optionTuples = new Array(args.length).fill(null);
    let sawSeparator = false;
    for (let i = 0; i < args.length; i += 1) {
      if (sawSeparator) {
        pattern.push('A');
        continue;
      }
      if (args[i] === '--') {
        sawSeparator = true;
        pattern.push('-');
        continue;
      }
      const tuple = this._parseOptional(args[i]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        pattern.push('O');
        optionTuples[i] = tuple;
      }
    }
    const patternString = pattern.join('');

    // --- Pass 2: consume options in argv order ---------------------------
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (!action.isHelp) namespace[action.dest] = null;
    }
    const seen = new Set();
    const extras = [];

    const takeAction = (action, argStrings) => {
      seen.add(action);
      if (action.isHelp) this.printHelp();
      if (action.nargs === 1) namespace[action.dest] = argStrings[0];
      else namespace[action.dest] = true;
    };

    const consumeOptional = (startIndex) => {
      let { action, optionString, sep, explicitArg } = optionTuples[startIndex];
      const actionTuples = [];
      let stop = startIndex + 1;

      for (;;) {
        // Unknown option: remember it and move on (it may be masked by a
        // higher-precedence error later).
        if (action === null) {
          extras.push(args[startIndex]);
          return startIndex + 1;
        }

        if (explicitArg !== null && explicitArg !== undefined) {
          const argCount = this._matchArgument(action, 'A');

          if (argCount === 0 && !this.prefixChars.includes(optionString[1]) && explicitArg !== '') {
            // A flag given a glued-on value: either an outright mistake
            // (`-h=x`, `--help=x`) or a short-option cluster (`-ha`).
            if (sep || this.prefixChars.includes(explicitArg[0])) {
              this._argumentError(action, `ignored explicit argument ${repr(explicitArg)}`);
            }
            actionTuples.push([action, []]);
            const char = optionString[0];
            optionString = char + explicitArg[0];
            const nextExplicitArg = explicitArg.slice(1) || null;
            if (this.optionStringActions.has(optionString)) {
              action = this.optionStringActions.get(optionString);
              explicitArg = nextExplicitArg;
              sep = null;
              continue;
            }
            extras.push(char + explicitArg);
            stop = startIndex + 1;
            break;
          }
          if (argCount === 1) {
            actionTuples.push([action, [explicitArg]]);
            stop = startIndex + 1;
            break;
          }
          this._argumentError(action, `ignored explicit argument ${repr(explicitArg)}`);
        }

        // No glued value: take the required count from the following tokens.
        const start = startIndex + 1;
        const argCount = this._matchArgument(action, patternString.slice(start));
        stop = start + argCount;
        actionTuples.push([action, args.slice(start, stop)]);
        break;
      }

      // Actions only fire once the whole option string parsed cleanly -- this
      // is why `-h=x` errors instead of printing help.
      for (const [act, actArgs] of actionTuples) takeAction(act, actArgs);
      return stop;
    };

    let index = 0;
    while (index < args.length) {
      if (pattern[index] === 'O') {
        index = consumeOptional(index);
      } else {
        // Plain arguments and the `--` separator: no positionals are declared,
        // so everything left over is unrecognized (the separator included).
        extras.push(args[index]);
        index += 1;
      }
    }

    // --- Pass 3: required options, then leftovers ------------------------
    const missing = this.actions.filter((a) => a.required && !seen.has(a)).map((a) => a.optionStrings.join('/'));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

