#!/usr/bin/env node
/**
 * Port of test7.py: derive two 24-byte PBKDF2 keys from one passphrase and two
 * different salts, printing each as lowercase hex.
 *
 *   key1 = pbkdf2.PBKDF2(a, b).read(24)   -> hex
 *   key2 = pbkdf2.PBKDF2(a, c).read(24)   -> hex
 *
 * Defaults inherited from the Python `pbkdf2` package: HMAC-SHA1 as the PRF and
 * 1000 iterations. Both are implemented from scratch under ./lib.
 */

import { ArgumentParser, ParserExit } from './lib/argparse.mjs';
import { PBKDF2 } from './lib/pbkdf2.mjs';
import { toHex } from './lib/bytes.mjs';

/** Last path component, i.e. argparse's default `prog` (basename of argv[0]). */
function basename(path) {
  const parts = String(path).split(/[/\\]/);
  return parts[parts.length - 1] || String(path);
}

function buildParser() {
  const parser = new ArgumentParser({ prog: basename(process.argv[1] || 'test7.mjs') });
  parser.addArgument(['--a'], { required: true }); // passphrase
  parser.addArgument(['--b'], { required: true }); // salt1
  parser.addArgument(['--c'], { required: true }); // salt2
  return parser;
}

function main() {
  const args = buildParser().parseArgs(process.argv.slice(2));

  // Each PBKDF2 object is a keystream: read(24) yields T_1 (20 bytes) followed
  // by the first 4 bytes of T_2.
  const key1 = new PBKDF2(args.a, args.b).read(24);
  process.stdout.write(`${toHex(key1)}\n`);

  const key2 = new PBKDF2(args.a, args.c).read(24);
  process.stdout.write(`${toHex(key2)}\n`);
}

try {
  main();
} catch (err) {
  if (err instanceof ParserExit) {
    // Setting exitCode (rather than calling process.exit) lets the stream
    // drain, so piped output is never truncated.
    if (err.text) {
      if (err.stream === 'stdout') process.stdout.write(err.text);
      else process.stderr.write(err.text);
    }
    process.exitCode = err.code;
  } else {
    throw err;
  }
}

