}

/** Greedy word wrap, standing in for `textwrap.wrap`. */
function wrapText(text, width) {
  const words = String(text).replace(/\s+/g, ' ').trim().split(' ').filter((w) => w !== '');
  const limit = Math.max(width, 1);
  const lines = [];
  let line = '';
  for (let word of words) {
    // break_long_words: a single word wider than the column gets chopped
    while (word.length > limit) {
      if (line !== '') {
