  const usage = [prog, parts.join(' ')].filter((s) => s).join(' ');

  // Terminal width, exactly as argparse derives it (COLUMNS, else the tty,
  // else 80 -- always minus 2).
  const textWidth = this._width();
  if (prefix.length + usage.length <= textWidth) {
    return `${prefix}${usage}\n`;
  }

  // Too long: wrap. Only optionals exist in this parser, no positionals.
  const optParts = parts.join(' ').match(USAGE_PART_RE) || [];

  const getLines = (pieces, indent, linePrefix) => {
    const lines = [];
    let line = [];
    let lineLen = (linePrefix !== undefined ? linePrefix.length : indent.length) - 1;
    for (const piece of pieces) {
      if (lineLen + 1 + piece.length > textWidth && line.length > 0) {
        lines.push(indent + line.join(' '));
        line = [];
        lineLen = indent.length - 1;
      }
      line.push(piece);
      lineLen += 1 + piece.length;
    }
    if (line.length > 0) lines.push(indent + line.join(' '));
    if (linePrefix !== undefined && lines.length > 0) lines[0] = lines[0].slice(indent.length);
    return lines;
  };

  let lines;
  if (prefix.length + prog.length <= 0.75 * textWidth) {
    // Short prog: options continue on the same line as the program name.
    const indent = ' '.repeat(prefix.length + prog.length + 1);
    lines = optParts.length > 0 ? getLines([prog, ...optParts], indent, prefix) : [prog];
  } else {
    // Long prog: it gets a line of its own.
    const indent = ' '.repeat(prefix.length);
    lines = [prog, ...getLines(optParts, indent)];
  }
  return `${prefix}${lines.join('\n')}\n`;
}

/** argparse's formatter width: terminal columns minus 2. */
_width() {
  const fromEnv = parseColumns(process.env.COLUMNS);
  if (fromEnv > 0) return fromEnv - INDENT;
  const tty = process.stdout && process.stdout.columns;
  if (Number.isInteger(tty) && tty > 0) return tty - INDENT;
  return FALLBACK_COLUMNS - INDENT;
}

formatHelp() {
  const width = this._width();
  // Column math straight out of argparse's HelpFormatter.
  const maxLength = Math.max(...this.actions.map((a) => this._formatInvocation(a).length + INDENT));
  const maxHelpPosition = Math.min(MAX_HELP_POSITION, Math.max(width - 20, INDENT * 2));
  const helpPosition = Math.min(maxLength + 2, maxHelpPosition);
  const helpWidth = Math.max(width - helpPosition, 11);
  const actionWidth = helpPosition - INDENT - 2;

  let out = `${this.formatUsage()}\noptions:\n`;
  for (const action of this.actions) {
    const invocation = this._formatInvocation(action);
    if (!action.help) {
      out += `${' '.repeat(INDENT)}${invocation}\n`;
      continue;
    }
    let indentFirst;
    if (invocation.length <= actionWidth) {
      // Help text sits in its column on the same line.
      out += `${' '.repeat(INDENT)}${invocation.padEnd(actionWidth)}  `;
      indentFirst = 0;
    } else {
      // Invocation is too wide: help text starts on the following line.
      out += `${' '.repeat(INDENT)}${invocation}\n`;
      indentFirst = helpPosition;
    }
    const helpLines = wrapText(action.help, helpWidth);
    out += `${' '.repeat(indentFirst)}${helpLines[0]}\n`;
    for (const line of helpLines.slice(1)) {
      out += `${' '.repeat(helpPosition)}${line}\n`;
    }
  }
  return out;
}

